    public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        // Initialize a visited array to keep track of n-tersections visited
        boolean[] visited = new boolean[n];

        // Initialize a queue to perform BFS
        Queue<Integer> queue = new LinkedList<>();

        // Mark the starting n-tersection as visited and add it to the queue
        visited[start[0]] = true;
        queue.add(start[0]);

        // Loop until the queue is empty
        while (!queue.isEmpty()) {
            // Get the next n-tersection to visit
            int current = queue.remove();

            // Check if the current n-tersection is the ending n-tersection
            if (current == end[0]) {
                // If so, return "can be travelled"
                return "can be travelled";
            }

            // Get the paths from the current n-tersection
            int[] currentPaths = paths[current];

            // Check if the current n-tersection has any paths
            if (currentPaths != null) {
                // If so, loop through the paths
                for (int i = 0; i < currentPaths.length; i++) {
                    // Get the next n-tersection to visit
                    int next = currentPaths[i];

                    // Check if the next n-tersection has already been visited
                    if (!visited[next]) {
                        // If not, mark the next n-tersection as visited and add it to the queue
                        visited[next] = true;
                        queue.add(next);
                    }
                }
            }
        }

        // If the queue is empty and the ending n-tersection was not found, return "cannot be travelled"
        return "cannot be travelled";
