public int minOperations(int n) {
    // Initialize the array arr with the given length n and elements (2 * i) + 1
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    // Initialize the minimum number of operations needed to make all elements equal
    int minOps = 0;

    // Iterate through each element in the array
    for (int i = 0; i < n; i++) {
        // If the current element is not equal to the first element, we need to perform an operation
        if (arr[i] != arr[0]) {
            // Find the index of the next element that is greater than the current element
            int next = 1;
            while (next < n && arr[next] <= arr[i]) {
                next++;
            }

            // If there is no next element greater than the current element, we need to perform an operation
            if (next == n) {
                // Perform an operation by decrementing the current element and incrementing the first element
                arr[i]--;
                arr[0]++;
                minOps++;
            } else {
                // Perform an operation by decrementing the current element and incrementing the next element
                arr[i]--;
                arr[next]++;
                minOps++;
            }
        }
    }

    // Return the minimum number of operations needed to make all elements equal
    return minOps;
}

