public int maxUniqueSplit(String s) {
    // Initialize variables
    int maxSubstrings = 0;
    Set<String> uniqueSubstrings = new HashSet<>();
    String currentSubstring = "";

    // Iterate through the string
    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        currentSubstring += currentChar;
        uniqueSubstrings.add(currentSubstring);

        // Check if the current substring can be split
        if (i < s.length() - 1) {
            String nextSubstring = s.substring(i + 1);
            if (uniqueSubstrings.contains(nextSubstring)) {
                maxSubstrings = Math.max(maxSubstrings, uniqueSubstrings.size());
                uniqueSubstrings.clear();
                currentSubstring = "";
            }
        }
    }

    // Check if there are any remaining substrings
    if (currentSubstring.length() > 0) {
        uniqueSubstrings.add(currentSubstring);
        maxSubstrings = Math.max(maxSubstrings, uniqueSubstrings.size());
    }

    return maxSubstrings;
}

