public static boolean isPowerOfTwo(int n) {
    // Initialize a flag to keep track of whether or not n is a power of two
    boolean isPowerOfTwo = false;

    // Iterate from 1 to the square root of n
    for (int i = 1; i <= Math.sqrt(n); i++) {
        // Check if i is a factor of n
        if (n % i == 0) {
            // If i is a factor of n, check if the other factor is equal to n / i
            if (n / i == i) {
                // If the other factor is equal to n / i, then n is a power of two
                isPowerOfTwo = true;
                break;
            }
        }
    }

    return isPowerOfTwo;
}

