private static boolean nextPermutation(int[] A) {
    int n = A.length;
    int i = n - 1;
    while (i > 0 && A[i-1] >= A[i]) i--;
    if (i == 0) return false;
    int j = n - 1;
    while (A[i-1] >= A[j]) j--;
    swap(A, i-1, j);
    reverse(A, i, n-1);
    return true;
}

private static void reverse(int[] A, int i, int j) {
    while (i < j) swap(A, i++, j--);
}

private static void swap(int[] A, int i, int j) {
    int tmp = A[i];
    A[i] = A[j];
    A[j] = tmp;
}
